import LottieView from 'lottie-react-native'
import { colors, Theme, useTheme } from '@/theme'
import { defineStyles } from '@/utils/defineStyles'
import { Text } from 'react-native'
import { useRef } from 'react'
import { LOTTIE_LOOP_COUNT } from '@/constants'

type LottieAnimationProps = {
	keypath: string
	source: string
	subTitle: string
	playNextAnimation: () => void
}

export const LottieAnimation = ({
	keypath,
	source,
	subTitle,
	playNextAnimation
}: LottieAnimationProps) => {
	const { theme, isDark } = useTheme()
	const animRef = useRef<LottieView>(null)
	const loopCountRef = useRef(0)

	const handleAnimationFinish = () => {
		loopCountRef.current++
		if (loopCountRef.current < LOTTIE_LOOP_COUNT) {
			animRef.current?.play()
		} else {
			playNextAnimation()
		}
	}

	return (
		<>
			<LottieView
				ref={animRef}
				autoPlay
				loop={false}
				style={styles.lottieAnimation}
				colorFilters={[
					{
						keypath: keypath,
						color: isDark ? colors[theme].gray[500] : colors[theme].gray[200]
					}
				]}
				source={source}
				onAnimationFinish={handleAnimationFinish}
			/>
			<Text style={styles.subTitle(theme, isDark)}>{subTitle}</Text>
		</>
	)
}

const styles = defineStyles({
	lottieAnimationContainer: {
		position: 'absolute',
		top: 0,
		left: 0,
		right: 0,
		bottom: 0,
		justifyContent: 'center',
		alignItems: 'center',
		gap: 20
	},
	lottieAnimation: {
		width: 72,
		height: 72
	},
	subTitle: (theme: Theme, isDark: boolean) => ({
		fontSize: 18,
		fontWeight: '500',
		color: isDark ? colors[theme].gray[500] : colors[theme].gray[200]
	})
})
